package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class TarUtils_formatNameBytes_TriageGen1Test {

    /**
     * Mock implementation of ZipEncoding to control ByteBuffer output.
     */
    private static class TestEncoding implements ZipEncoding {
        private final String content;

        TestEncoding(String content) {
            this.content = content;
        }

        @Override
        public ByteBuffer encode(String s) {
            // We use wrap to ensure b.array() and b.arrayOffset() work as expected in the source code
            return ByteBuffer.wrap(s.getBytes(StandardCharsets.UTF_8));
        }
    }

    @Test
    public void testFormatNameBytes_ExactLength() throws IOException {
        String name = "test";
        byte[] buf = new byte[10];
        int offset = 0;
        int length = 4;
        ZipEncoding encoding = new TestEncoding("test");

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(offset + length, result);
        assertEquals("test", new String(buf, 0, 4, StandardCharsets.UTF_8));
    }

    @Test
    public void testFormatNameBytes_PaddingWithNul() throws IOException {
        String name = "abc";
        byte[] buf = new byte[10];
        int offset = 1;
        int length = 5;
        ZipEncoding encoding = new TestEncoding("abc");

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(offset + length, result);
        // Check content: [0, 'a', 'b', 'c', 0, 0, 0, 0, 0, 0]
        assertEquals((byte) 'a', buf[1]);
        assertEquals((byte) 'b', buf[2]);
        assertEquals((byte) 'c', buf[3]);
        assertEquals((byte) 0, buf[4]);
        assertEquals((byte) 0, buf[5]);
    }

    @Test
    public void testFormatNameBytes_TruncateByLength() throws IOException {
        // Name is longer than the provided buffer length
        String name = "longname";
        byte[] buf = new byte[4];
        int offset = 0;
        int length = 4;
        ZipEncoding encoding = new TestEncoding("longname");

        // The loop in source: while (b.limit() > length && len > 0)
        // It will try "longname", then "longnam", "longna", "longn", "long", "lon", "lo", "l"
        // Eventually it finds a substring that fits in 4 bytes.
        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(offset + length, result);
        assertEquals("long", new String(buf, 0, 4, StandardCharsets.UTF_8));
    }

    @Test
    public void testFormatNameBytes_EmptyName() throws IOException {
        String name = "";
        byte[] buf = new byte[5];
        int offset = 0;
        int length = 5;
        ZipEncoding encoding = new TestEncoding("");

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(offset + length, result);
        for (int i = 0; i < 5; i++) {
            assertEquals(0, buf[i]);
        }
    }

    @Test
    public void testFormatNameBytes_NameIsZeroLengthButBufferIsLonger() throws IOException {
        String name = "";
        byte[] buf = new byte[5];
        int offset = 0;
        int length = 5;
        // Mock encoding to return something that satisfies the loop logic
        ZipEncoding encoding = mock(ZipEncoding.class);
        when(encoding.encode(anyString())).thenReturn(ByteBuffer.wrap(new byte[0]));

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(5, result);
        for (int i = 0; i < 5; i++) {
            assertEquals(0, buf[i]);
        }
    }

    @Test
    public void testFormatNameBytes_EncodingException() throws IOException {
        String name = "test";
        byte[] buf = new byte[10];
        ZipEncoding encoding = mock(ZipEncoding.class);
        when(encoding.encode(anyString())).thenThrow(new IOException("Encoding failed"));

        try {
            TarUtils.formatNameBytes(name, buf, 0, 5, encoding);
        } catch (IOException e) {
            assertEquals("Encoding failed", e.getMessage());
        }
    }

    @Test
    public void testFormatNameBytes_WithOffset() throws IOException {
        String name = "hi";
        byte[] buf = new byte[10];
        int offset = 5;
        int length = 2;
        ZipEncoding encoding = new TestEncoding("hi");

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(7, result);
        assertEquals((byte) 'h', buf[5]);
        assertEquals((byte) 'i', buf[6]);
        assertEquals(0, buf[7]); // check padding starts after offset + length
    }
}
